INSERT INTO dialogues(dialogue_key,language_level_id,scenario,opening_initiator,scene_quality_rationale) VALUES
('dlg-de-a1-food-substitutes',@level,'مشتری موجودبودن دو گروه غذایی را می‌پرسد و پاسخ جایگزین موجود را معرفی می‌کند.','app','دو جفت سؤال‌وجواب منبع‌دارِ «موجود نیست، اما جایگزین هست» برای مهارت مدیریت نبودن یک قلم انتخاب شده‌اند.')
