INSERT INTO activities(activity_key,lesson_id,position_index,activity_type,instruction_fa,selection_reason,dialogue_id,payload,transformations,audio_text_target,audio_status) VALUES
('act-de-a1-food-combinations-review-conversation',@lesson,1,'conversation_speaking','بپرس چه چیزی موجود است و جایگزین پیشنهادی را بفهم.','دو جفت پرسش‌وپاسخ منبع‌دار الگوی نبودن یک قلم و وجود جایگزین را در بافت سفارش نشان می‌دهند.',(SELECT id FROM dialogues WHERE dialogue_key='dlg-de-a1-food-substitutes' LIMIT 1),CAST('{"interaction":"read_aloud_exchange","openingInitiator":"app"}' AS JSON),CAST('["verbatim_dialogue","persian_translation_added","character_metadata_added"]' AS JSON),NULL,'not_required')
INSERT INTO activities(activity_key,lesson_id,position_index,activity_type,instruction_fa,selection_reason,dialogue_id,payload,transformations,audio_text_target,audio_status) VALUES
('act-de-a1-food-combinations-review-matching',@lesson,2,'matching','هر قلم ناموجود را به جایگزین منبع‌دارش وصل کن.','چهار جفت مختلف نشان می‌دهند الگو به یک خوراکی محدود نیست.',NULL,CAST('{"pairs":[{"left":"Käse","leftFa":"پنیر","right":"Wurst","rightFa":"سوسیس"},{"left":"Gemüse","leftFa":"سبزیجات","right":"Obst","rightFa":"میوه"},{"left":"Milch","leftFa":"شیر","right":"Tee","rightFa":"چای"},{"left":"Wasser","leftFa":"آب","right":"Kakao","rightFa":"کاکائو"}]}' AS JSON),CAST('["source_items_grouped_for_matching","persian_translation_added"]' AS JSON),NULL,'not_required')
INSERT INTO activities(activity_key,lesson_id,position_index,activity_type,instruction_fa,selection_reason,dialogue_id,payload,transformations,audio_text_target,audio_status) VALUES
('act-de-a1-food-combinations-review-order',@lesson,3,'fill_blank','پاسخ جایگزین را کامل کن.','تکمیل aber es gibt ساختار کاربردی پاسخ به نبودن یک قلم را فعال می‌کند.',NULL,CAST('{"sourceText":"Nein, aber es gibt Tee.","sourceTextFa":"نه، اما چای هست.","blankedText":"Nein, aber es gibt ___.","blankedTextFa":"نه، اما ___ هست.","choices":["Tee","Milch","Wasser"],"choicesFa":["چای","شیر","آب"],"answer":"Tee"}' AS JSON),CAST('["source_sentence_blank_created","persian_translation_added"]' AS JSON),NULL,'not_required')
INSERT INTO dialogues(dialogue_key,language_level_id,scenario,opening_initiator,scene_quality_rationale) VALUES
('dlg-de-a1-reschedule-exact-time',@level,'یک زمان مشخص رد می‌شود و بعد یک زمان و محل دقیق جایگزین تأیید می‌شود.','app','پاسخ رد ساعت از تمرین ۸۸۶ و جفت توافق زمان/مکان از گفت‌وگوی ۸۷۷ عین منبع حفظ شده‌اند.')
