INSERT INTO dialogue_turns(turn_key,dialogue_id,position_index,speaker_character_id,speaker_identity_origin,speaker_gender_evidence,text_target,translation_fa,learner_turn,audio_status) VALUES
('turn-de-a1-reschedule-exact-time-3',@dlg,3,(SELECT id FROM characters WHERE character_key='char-de-iris' LIMIT 1),'app_assigned','unspecified','Dann warte ich morgen am Kino 19.45 Uhr. Ist Ihnen das Recht?','پس فردا ساعت ۱۹:۴۵ جلوی سینما منتظرتان می‌مانم. برایتان مناسب است؟',FALSE,'pending')
INSERT INTO dialogue_turns(turn_key,dialogue_id,position_index,speaker_character_id,speaker_identity_origin,speaker_gender_evidence,text_target,translation_fa,learner_turn,audio_status) VALUES
('turn-de-a1-reschedule-exact-time-4',@dlg,4,(SELECT id FROM characters WHERE character_key='char-de-paul' LIMIT 1),'app_assigned','unspecified','Ja, das passt mir. Gut, morgen Abend am Kino.','بله، برایم مناسب است. خوب، فردا شب جلوی سینما.',TRUE,'pending')
INSERT INTO activities(activity_key,lesson_id,position_index,activity_type,instruction_fa,selection_reason,dialogue_id,payload,transformations,audio_text_target,audio_status) VALUES
('act-de-a1-time-review-conversation',@lesson,1,'conversation_speaking','یک ساعت نامناسب را رد کن و زمان جایگزین را تأیید کن.','جفت‌های منبع‌دار ساعت ۱۲ و ۱۹:۴۵، چرخهٔ رد → پیشنهاد → تأیید را کامل می‌کنند.',(SELECT id FROM dialogues WHERE dialogue_key='dlg-de-a1-reschedule-exact-time' LIMIT 1),CAST('{"interaction":"read_aloud_exchange","openingInitiator":"app"}' AS JSON),CAST('["other","persian_translation_added","character_metadata_added"]' AS JSON),NULL,'not_required')
INSERT INTO activities(activity_key,lesson_id,position_index,activity_type,instruction_fa,selection_reason,dialogue_id,payload,transformations,audio_text_target,audio_status) VALUES
('act-de-a1-time-review-matching',@lesson,2,'multiple_choice','کدام جمله یعنی «این زمان برای من مناسبه»؟','زبان‌آموز باید پاسخ توافق را از رد زمان تشخیص دهد.',NULL,CAST('{"options":[{"textTarget":"Ja, das passt mir.","translationFa":"بله، برایم مناسب است.","correct":true},{"textTarget":"Es tut mir leid, um 12 Uhr geht es nicht.","translationFa":"متأسفم، ساعت ۱۲ نمی‌شود.","correct":false},{"textTarget":"Morgen geht es vielleicht.","translationFa":"فردا شاید بشود.","correct":false}]}' AS JSON),CAST('["options_selected_from_source_material","persian_translation_added"]' AS JSON),NULL,'not_required')
INSERT INTO activities(activity_key,lesson_id,position_index,activity_type,instruction_fa,selection_reason,dialogue_id,payload,transformations,audio_text_target,audio_status) VALUES
('act-de-a1-time-review-order',@lesson,3,'word_order','پرسش قرار ساعت ۱۲ را بساز.','بازسازی پرسش، الگوی um + ساعت را در یک درخواست واقعی تثبیت می‌کند.',NULL,CAST('{"sourceText":"Warten Sie um 12 Uhr auf mich?","sourceTextFa":"ساعت ۱۲ منتظر من می‌مانید؟","tokens":["Warten","Sie","um","12","Uhr","auf","mich?"],"answer":["Warten","Sie","um","12","Uhr","auf","mich?"]}' AS JSON),CAST('["sentence_tokenized_for_word_order","persian_translation_added"]' AS JSON),NULL,'not_required')
INSERT INTO dialogues(dialogue_key,language_level_id,scenario,opening_initiator,scene_quality_rationale) VALUES
('dlg-de-a1-hotel-restaurant-location',@level,'مسافر ابتدا هتل را پیدا می‌کند و بعد می‌پرسد آیا رستورانی در آن هست.','learner','چهار نوبت نخست گفت‌وگوی ۵-۲ منبع بدون ساخت جملهٔ تازه استفاده شده و موقعیت نسبی رستوران نسبت به هتل را آموزش می‌دهد.')
