INSERT INTO dialogue_turns(turn_key,dialogue_id,position_index,speaker_character_id,speaker_identity_origin,speaker_gender_evidence,text_target,translation_fa,learner_turn,audio_status) VALUES
('turn-de-a1-hotel-restaurant-location-4',@dlg,4,(SELECT id FROM characters WHERE character_key='char-de-iris' LIMIT 1),'app_assigned','unspecified','Ja gewiss! Ein Restaurant mit einfacher Küche, besonders zum Abendessen. Aber ich könnte Ihnen ein anderes Restaurant empfehlen. Es heißt ''Alt-Wien'', und es gibt dort das beste Frühstück. Das Restaurant ist links neben dem Hotel, um die Ecke.','بله، حتماً! یک رستوران با غذای ساده، مخصوصاً برای شام. اما می‌توانم رستوران دیگری پیشنهاد کنم. اسمش «Alt-Wien» است و آنجا بهترین صبحانه را دارند. رستوران سمت چپ هتل، سرِ پیچ است.',FALSE,'pending')
INSERT INTO activities(activity_key,lesson_id,position_index,activity_type,instruction_fa,selection_reason,dialogue_id,payload,transformations,audio_text_target,audio_status) VALUES
('act-de-a1-directions-places-review-conversation',@lesson,1,'conversation_speaking','خودت گفت‌وگو را شروع کن: هتل را پیدا کن و بعد دربارهٔ رستوران داخل یا کنار آن بپرس.','چهار نوبت نخست گفت‌وگوی منبع یک زنجیرهٔ واقعیِ مقصد → امکان → موقعیت نسبی می‌سازند.',(SELECT id FROM dialogues WHERE dialogue_key='dlg-de-a1-hotel-restaurant-location' LIMIT 1),CAST('{"interaction":"read_aloud_exchange","openingInitiator":"learner"}' AS JSON),CAST('["verbatim_dialogue","persian_translation_added","character_metadata_added"]' AS JSON),NULL,'not_required')
INSERT INTO activities(activity_key,lesson_id,position_index,activity_type,instruction_fa,selection_reason,dialogue_id,payload,transformations,audio_text_target,audio_status) VALUES
('act-de-a1-directions-places-review-matching',@lesson,2,'multiple_choice','رستوران «Alt-Wien» نسبت به هتل کجاست؟','پاسخ از جملهٔ منبع‌دار استخراج می‌شود و فهم موقعیت نسبی را می‌سنجد.',NULL,CAST('{"options":[{"textTarget":"links neben dem Hotel, um die Ecke","translationFa":"سمت چپ هتل، سرِ پیچ","correct":true},{"textTarget":"Rechts um die Ecke","translationFa":"سرِ پیچ سمت راست","correct":false},{"textTarget":"immer geradeaus","translationFa":"همیشه مستقیم","correct":false}]}' AS JSON),CAST('["options_selected_from_source_material","persian_translation_added"]' AS JSON),NULL,'not_required')
INSERT INTO activities(activity_key,lesson_id,position_index,activity_type,instruction_fa,selection_reason,dialogue_id,payload,transformations,audio_text_target,audio_status) VALUES
('act-de-a1-directions-places-review-order',@lesson,3,'word_order','پرسش محل هتل را بساز.','پرسش Wo ist hier ... الگوی مستقیم پیدا کردن یک مکان را فعال می‌کند.',NULL,CAST('{"sourceText":"Wo ist hier ein Hotel?","sourceTextFa":"اینجا یک هتل کجاست؟","tokens":["Wo","ist","hier","ein","Hotel?"],"answer":["Wo","ist","hier","ein","Hotel?"]}' AS JSON),CAST('["sentence_tokenized_for_word_order","persian_translation_added"]' AS JSON),NULL,'not_required')
