('act-de-a1-services-permission-review-conversation',@lesson,1,'conversation_speaking','از کارمند فروشگاه برای پیدا کردن سایز مناسب کمک بگیر و اتاق پرو را پیدا کن.','گفت‌وگوی پیوستهٔ منبع یک تعامل خدماتی کامل و طبیعی ارائه می‌کند.',(SELECT id FROM dialogues WHERE dialogue_key='dlg-de-a1-clothing-store-help' LIMIT 1),CAST('{"interaction":"read_aloud_exchange","openingInitiator":"app"}' AS JSON),CAST('["verbatim_dialogue","persian_translation_added","character_metadata_added"]' AS JSON),NULL,'not_required')
INSERT INTO activities(activity_key,lesson_id,position_index,activity_type,instruction_fa,selection_reason,dialogue_id,payload,transformations,audio_text_target,audio_status) VALUES
('act-de-a1-services-permission-review-choice',@lesson,2,'choose_response','به «Darf ich Ihnen helfen?» پاسخ مناسب را انتخاب کن.','پاسخ درست دقیقاً درخواست کمک مشخص برای سایز مناسب است.',NULL,CAST('{"promptTarget":"Darf ich Ihnen helfen?","promptFa":"می‌توانم کمکتان کنم؟","options":[{"textTarget":"Ja, können Sie mir helfen, diesen Rock in meiner Größe zu finden?","translationFa":"بله، می‌توانید کمکم کنید این دامن را در سایز من پیدا کنم؟","correct":true},{"textTarget":"Danke. Wo ist die Umkleidekabine?","translationFa":"ممنون. اتاق پرو کجاست؟","correct":false},{"textTarget":"Dort drüben.","translationFa":"آن طرف.","correct":false}]}' AS JSON),CAST('["options_selected_from_source_material","persian_translation_added"]' AS JSON),NULL,'not_required')
INSERT INTO activities(activity_key,lesson_id,position_index,activity_type,instruction_fa,selection_reason,dialogue_id,payload,transformations,audio_text_target,audio_status) VALUES
('act-de-a1-services-permission-review-order',@lesson,3,'fill_blank','پرسش محل اتاق پرو را کامل کن.','واژهٔ کلیدیِ خدمت فروشگاه در قالب پرسش واقعی تثبیت می‌شود.',NULL,CAST('{"sourceText":"Danke. Wo ist die Umkleidekabine?","sourceTextFa":"ممنون. اتاق پرو کجاست؟","blankedText":"Danke. Wo ist die ___?","blankedTextFa":"ممنون. ___ کجاست؟","choices":["Umkleidekabine","Größe","Rock"],"choicesFa":["اتاق پرو","سایز","دامن"],"answer":"Umkleidekabine"}' AS JSON),CAST('["source_sentence_blank_created","persian_translation_added"]' AS JSON),NULL,'not_required')
INSERT INTO dialogues(dialogue_key,language_level_id,scenario,opening_initiator,scene_quality_rationale) VALUES
('dlg-de-a1-urgent-service-help',@level,'پاول می‌گوید کمک لازم دارد و بعد محل پیدا کردن پزشک را می‌پرسد؛ آیریس جهت کلی را نشان می‌دهد.','learner','جمله‌ها همگی مستقیماً از منابع ثبت‌شده آمده‌اند؛ فقط برای ساخت یک سناریوی خدمات ضروری کنار هم قرار گرفته‌اند.')
