('act-de-a1-services-help-review-conversation',@lesson,1,'conversation_speaking','خودت گفت‌وگو را شروع کن: بگو کمک لازم داری و محل پزشک را بپرس.','جمله‌های کوتاه از منابع معتبر در یک سناریوی خدمات ضروری کنار هم قرار گرفته‌اند.',(SELECT id FROM dialogues WHERE dialogue_key='dlg-de-a1-urgent-service-help' LIMIT 1),CAST('{"interaction":"read_aloud_exchange","openingInitiator":"learner"}' AS JSON),CAST('["other","persian_translation_added","character_metadata_added"]' AS JSON),NULL,'not_required')
