('act-de-a1-services-help-review-response',@lesson,2,'multiple_choice','اگر دنبال پزشک هستی، کدام پرسش را می‌گویی؟','سه پرسش منبع‌دار از حوزه‌های مختلف، انتخاب هدف ارتباطی درست را می‌سنجند.',NULL,CAST('{"options":[{"textTarget":"Wo finde ich einen Arzt?","translationFa":"کجا می‌توانم یک پزشک پیدا کنم؟","correct":true},{"textTarget":"Wo ist der Bahnhof?","translationFa":"ایستگاه قطار کجاست؟","correct":false},{"textTarget":"Was brauchen Sie?","translationFa":"چه چیزی لازم دارید؟","correct":false}]}' AS JSON),CAST('["options_selected_from_source_material","persian_translation_added"]' AS JSON),NULL,'not_required')
