('act-de-a1-services-help-review-matching',@lesson,3,'word_order','عبارت درخواست کمک را بساز.','یک عبارت بقای بسیار کوتاه و مستقیم به بازیابی فعال منتقل می‌شود.',NULL,CAST('{"sourceText":"Ich brauche Hilfe.","sourceTextFa":"کمک لازم دارم.","tokens":["Ich","brauche","Hilfe."],"answer":["Ich","brauche","Hilfe."]}' AS JSON),CAST('["sentence_tokenized_for_word_order","persian_translation_added"]' AS JSON),NULL,'not_required')
