('act-de-a1-forms-review-conversation',@lesson,1,'conversation_speaking','نام و نام خانوادگی نمونه را حرف‌به‌حرف هجی کن.','دو دستور و دو نمونهٔ تمرین ۲۹۸ به یک نقش‌آفرینی فرم تبدیل شده‌اند.',(SELECT id FROM dialogues WHERE dialogue_key='dlg-de-a1-spell-personal-data' LIMIT 1),CAST('{"interaction":"read_aloud_exchange","openingInitiator":"app"}' AS JSON),CAST('["other","persian_translation_added","character_metadata_added"]' AS JSON),NULL,'not_required')
