('act-de-a1-forms-review-matching',@lesson,2,'matching','هر فیلد را به نمونهٔ درست منبع وصل کن.','چهار نمونهٔ همان تمرین نشان می‌دهند هجی‌کردن فقط برای نام کوچک نیست.',NULL,CAST('{"pairs":[{"left":"Vorname","leftFa":"نام کوچک","right":"Marcus","rightFa":"مارکوس"},{"left":"Familienname","leftFa":"نام خانوادگی","right":"Clinton","rightFa":"کلینتون"},{"left":"Straßenname","leftFa":"نام خیابان","right":"Hauptstraße","rightFa":"هاوپت‌اشتراسه"},{"left":"Stadt","leftFa":"شهر","right":"Werdau","rightFa":"ورداو"}]}' AS JSON),CAST('["source_items_grouped_for_matching","persian_translation_added"]' AS JSON),NULL,'not_required')
INSERT INTO activities(activity_key,lesson_id,position_index,activity_type,instruction_fa,selection_reason,dialogue_id,payload,transformations,audio_text_target,audio_status) VALUES
('act-de-a1-forms-review-order',@lesson,3,'word_order','درخواست «لطفاً آهسته هجی کنید» را بساز.','این جمله مستقیماً مهارت هجی‌کردن را به مدیریت سرعت گفتار وصل می‌کند.',NULL,CAST('{"sourceText":"Können Sie das bitte langsam buchstabieren?","sourceTextFa":"می‌توانید لطفاً آن را آهسته هجی کنید؟","tokens":["Können","Sie","das","bitte","langsam","buchstabieren?"],"answer":["Können","Sie","das","bitte","langsam","buchstabieren?"]}' AS JSON),CAST('["sentence_tokenized_for_word_order","persian_translation_added"]' AS JSON),NULL,'not_required')
