UPDATE lessons SET unit_id=@unit,title_fa='نداریم؛ این چطور؟',activity_selection_rationale='این درس مهارت تازهٔ مدیریت ناموجودبودن یک قلم را اضافه می‌کند؛ زبان‌آموز فقط سفارش حفظ‌شده نمی‌دهد و باید جایگزین را بفهمد.',sequence_rationale='مکالمه الگوی سؤال/جایگزین را معرفی می‌کند، تطبیق چهار جفت دامنه را گسترش می‌دهد و تکمیل جمله ساختار aber es gibt را تثبیت می‌کند.',template_signature='conversation_speaking>matching>fill_blank',status='final',audio_status='pending',notes='محتوای قبلی این درس به‌طور کامل با یک هدف آموزشی مستقل و منبع‌دار جایگزین شده است.' WHERE id=@lesson;
